  'table-tool2-cost' => 'মাঝারি মূল্য ছোট দল এবং পেশাদারদের জন্য উপযুক্ত।',
  'table-tool2-usecase' => 'ঘন ঘন সম্পাদকদের গতি এবং সহযোগিতা সমর্থন প্রয়োজন।',
  'table-tool3' => 'পিডিএফ গিয়ার',
